<?php
declare(strict_types=1);
require_once __DIR__.'/document_extract.php';
function cuttingImportRecord(array $c,string $id):array{
 $r=one('SELECT * FROM document_imports WHERE id=? AND company_id=? AND actor_id=?',[$id,$c['id'],$_SESSION['user_id']]);if(!$r)fail('Источник импорта недоступен',404);return $r;
}
function cuttingImportPublic(array $r):array{return ['id'=>$r['id'],'name'=>$r['display_name'],'format'=>$r['extension'],'sha256'=>$r['source_hash'],'text'=>$r['raw_text'],'metadata'=>decode($r['metadata_json'])];}
function cuttingDocxTable(string $path):?string{
 $zip=new DocumentZip($path);if(!$zip->has('word/document.xml'))return null;$dom=documentXml($zip->read('word/document.xml'));$xp=new DOMXPath($dom);$lines=[];foreach($xp->query('//*[local-name()="tbl"]/*[local-name()="tr"]') as $row){$cells=[];foreach($xp->query('./*[local-name()="tc"]',$row) as $cell){$texts=[];foreach($xp->query('.//*[local-name()="t"]',$cell) as $t)$texts[]=$t->textContent;$cells[]=str_replace(["\t","\r","\n"],' ',implode(' ',$texts));}$lines[]=implode("\t",$cells);}return $lines?implode("\n",$lines):null;
}
function cuttingLocalProcess(array $command,int $limit=20):string{
 if(!function_exists('proc_open'))fail('Локальное распознавание недоступно на этом хостинге. Сохранённый источник можно дополнить текстом вручную.',503);$pipes=[];$process=@proc_open($command,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($process))fail('Не удалось запустить локальное распознавание',503);fclose($pipes[0]);stream_set_blocking($pipes[1],false);stream_set_blocking($pipes[2],false);$out='';$error='';$start=microtime(true);$exit=-1;
 try{while(true){$out.=stream_get_contents($pipes[1]);$error.=stream_get_contents($pipes[2]);if(strlen($out)>DOCUMENT_MAX_TEXT||strlen($error)>1048576)fail('Результат распознавания слишком велик',413);$status=proc_get_status($process);if(!$status['running']){$exit=$status['exitcode'];break;}if(microtime(true)-$start>$limit){proc_terminate($process);fail('Распознавание страницы прервано по времени. Источник и готовые страницы сохранены.',503);}usleep(20000);}$out.=stream_get_contents($pipes[1]);}finally{foreach([1,2] as $i)fclose($pipes[$i]);$closed=proc_close($process);if($exit<0)$exit=$closed;}if($exit!==0)fail('Не удалось распознать выбранную страницу. Проверьте качество изображения и локальный OCR.',422);return $out;
}
function cuttingRecognizeFile(string $source,string $extension,int $page,string $directory):string{
 global $config;$tesseract=$config['ocr_binary']??'/usr/bin/tesseract';if(!is_file($tesseract)||!is_executable($tesseract))fail('На хостинге не подключён локальный OCR. Укажите ocr_binary в конфигурации или вставьте распознанную таблицу вручную. Исходник сохранён.',503);$image=$source;$temp=null;
 try{if($extension==='pdf'){$converter=$config['pdf_image_binary']??'/usr/bin/pdftoppm';if(!is_file($converter)||!is_executable($converter))fail('Для сканов PDF нужен локальный pdftoppm (pdf_image_binary). Исходник сохранён.',503);$prefix=$directory.'/ocr-'.uid();$temp=$prefix.'.png';cuttingLocalProcess([$converter,'-f',(string)$page,'-l',(string)$page,'-singlefile','-scale-to','2200','-png',$source,$prefix],12);if(!is_file($temp))fail('Страница PDF отсутствует или недоступна');$image=$temp;}elseif($page!==1)fail('У изображения только одна страница');$language=$config['ocr_languages']??'rus+eng';if(!is_string($language)||!preg_match('/^[a-zA-Z_+]+$/D',$language))fail('Проверьте языки OCR в конфигурации',503);return documentCleanText(cuttingLocalProcess([$tesseract,$image,'stdout','-l',$language,'--psm','6'],20));}finally{if($temp&&is_file($temp))unlink($temp);}
}
function cuttingImportPreview(array $input,array $c,array $o):array{
 $document=null;if(!empty($input['document_id']))$document=cuttingImportRecord($c,textField($input,'document_id',32,true));$text=textField($input,'text',300000,true);$separator=$input['separator']??'tab';$delimiter=['tab'=>"\t",'semicolon'=>';','comma'=>','][$separator]??null;if($delimiter===null)fail('Выберите разделитель');$columns=$input['columns']??[];$map=[];foreach(['color','size','quantity','model','due'] as $k)$map[$k]=numberField($columns,$k,0,100,true);foreach(['color','size','quantity'] as $k)if($map[$k]===null)fail('Сопоставьте цвет, размер и количество');$strategy=$input['duplicates']??'keep';if(!in_array($strategy,['keep','sum','replace'],true))fail('Выберите обработку повторов');$header=numberField($input,'skip_rows',0,100);$lines=preg_split('/\R/u',$text);if(count($lines)>10001)fail('Разделите таблицу: максимум 10000 строк за один перенос');$variants=goalVariants($o);$rows=[];$errors=[];$seen=[];
 foreach($lines as $index=>$line){if($index<$header||trim($line)==='')continue;$cells=str_getcsv($line,$delimiter,'"','');$get=fn($k)=>$map[$k]===null?'':trim($cells[$map[$k]]??'');$color=$get('color');$size=$get('size');$rawQ=$get('quantity');$model=$get('model');$matches=array_values(array_filter($variants,fn($v)=>$v['color']===$color&&$v['size']===$size));$q=filter_var($rawQ,FILTER_VALIDATE_INT);if($q===false||$q<0||count($matches)!==1||($model!==''&&$model!==$o['product'])){$errors[]=['line'=>$index+1,'message'=>'Проверьте модель, цвет, размер и целое неотрицательное количество'];continue;}$variant=$matches[0];$id=$variant['id'];$row=['variant_id'=>$id,'color'=>$color,'size'=>$size,'quantity'=>(int)$q,'due'=>$get('due')?:$o['deadline'].' 09:00:00','source_lines'=>[$index+1],'document_id'=>$document['id']??null,'source_hash'=>$document['source_hash']??hash('sha256',$text)];
  if(isset($seen[$id])){if($strategy==='keep'){$errors[]=['line'=>$index+1,'message'=>'Повтор варианта: выберите явное суммирование или замену'];continue;}$at=$seen[$id];if($strategy==='sum'){if($rows[$at]['due']!==$row['due']){$errors[]=['line'=>$index+1,'message'=>'Разные сроки одного варианта разнесите на отдельные волны'];continue;}$rows[$at]['quantity']+=$q;$rows[$at]['source_lines'][]=$index+1;}else $rows[$at]=$row;}else{$seen[$id]=count($rows);$rows[]=$row;}
 }
 foreach($rows as $row){$v=array_column($variants,null,'id')[$row['variant_id']];if($row['quantity']>$v['quantity'])$errors[]=['line'=>$row['source_lines'][0],'message'=>'Потребность превышает количество варианта в заказе'];try{manufacturingTimestamp($row['due'],$c['passport']['timezone']);}catch(AppError){$errors[]=['line'=>$row['source_lines'][0],'message'=>'Проверьте дату и время потребности'];}}
 return ['rows'=>$rows,'errors'=>$errors,'quantity'=>array_sum(array_column($rows,'quantity')),'document'=>$document?array_intersect_key(cuttingImportPublic($document),array_flip(['id','name','format','sha256'])):null,'status'=>$errors?'needs_review':'ready','notice'=>'Предпросмотр не меняет заказ и тарифы. Применение меняет только текущую волну; сохраните её отдельно.'];
}
